"""Authored lexical material aligned to imported customer IDs; references are not pasted verbatim."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
res=root/'ai-hack-test/Assets/CafeSim/Resources'
# opener, ending, match, correction, good review, bad review, topic thought
styles={
'cus_elder':('다방에서 맛보던 향이 문득 생각나는구먼.',' 부탁하겠네.','허허, 바라던 맛의 방향이로군.','내가 빗대어 말한 맛을 다시 살펴봐 주겠나?','잔 하나에 옛 다방의 여유가 담겼구먼.','내가 설명한 맛과는 거리가 있어 아쉽구먼.','옛 다방에서 커피 향을 먼저 맡던 일을 떠올리고 있네.'),
'cus_gyeongsang':('장바구니 잠깐 내려놓고 고를게예.',' 주이소.','맞네예. 딱 이쪽 맛입니더.','내 고른 맛이랑 다르네예. 한 번 봐주이소.','내 취향대로 챙겨줘서 고맙네예.','내 말이 짧았어도 고른 맛은 따로 있었어예.','시장 골목에서 뭐 샀나 장바구니를 정리하고 있어예.'),
'cus_jeolla':('친구들이랑 얘기하다가 그 맛이 생각났당께요.',' 부탁해요잉.','맞아잉, 내가 찾던 쪽이여.','내가 말한 거시기가 이쪽은 아닌디, 다시 봐줘요잉.','입맛에 맞게 챙겨주니 모임 얘기도 더 즐겁겠네잉.','내가 말한 맛하고 달라서 쪼끔 아쉽당께요.','친구들이 추천한 드라마 얘기를 떠올리고 있어요잉.'),
'cus_chungcheong':('다들 고르는 걸 보니 나도 한 잔 생각나네유.',' 주시면 좋겠슈.','아, 이 정도면 내 생각하고 맞아유.','그쪽도 괜찮긴 한데유, 내가 바란 맛은 좀 달랐어유.','내 뜻을 알아봐 주니 마음이 편해유.','내가 에둘러 말했어도 바라던 맛은 있었거든유.','집에서 기다리는 소식이 있나 휴대폰을 살펴보고 있어유.'),
'cus_gangwon':('산길 걷고 내려오니 한 잔 생각나드래요.',' 부탁드래요.','좋네요. 바랐던 맛으로 왔드래요.','내가 고른 맛하고 다른 것 같드래요. 한번 봐주실래요?','산길 끝에 내 취향 한 잔이 기다리니 좋네요.','걷는 동안 떠올린 맛하고 달라서 아쉽드래요.','산에서 만난 강아지가 자꾸 생각나드래요.'),
'cus_jeju':('고향 밭에서 맡던 향이 생각남수다.',' 부탁드리쿠다.','내 고른 쪽이 맞수다. 반갑네요.','내 말한 맛을 다시 확인해 줍서. 천천히 다시 말해드리쿠다.','고향 얘기까지 담아 맛을 골라주니 반갑수다.','바란 향하고 다르니 아쉽수다.','바다 건너 손주에게 귤밭 사진을 보여줄 생각을 하고 있수다.'),
'cus_sea':('고향에서 가족과 나눠 마시던 맛이 생각났어요.',' 부탁드려요.','맞아요. 제가 설명한 맛이 이런 방향이에요.','고향 음료에 빗댄 부분을 다시 확인해 주실래요?','고향 맛을 설명한 말을 잘 들어주셔서 반가워요.','제가 비교해서 말씀드린 맛과는 조금 달랐어요.','고향 가족에게 오늘 먹은 음식을 어떻게 설명할지 생각하고 있어요.'),
'cus_west':('오늘은 Korean taste를 조금 더 알아보고 싶어요.',' please, 부탁드려요.','Yes, 제가 말한 맛의 방향이에요.','제가 설명한 taste와 달라요. 다시 확인할 수 있을까요?','새로운 맛을 제 취향에 맞게 경험해서 좋았어요.','기대한 맛과 달라서 아쉬워요. 그래도 제 뜻은 다시 말할 수 있어요.','여행 수첩에 오늘 배운 한국어를 적고 있어요.'),
'cus_japan':('여행 중에 익숙한 맛과 새로운 맛을 비교하고 있어요.',' 부탁드리겠습니다.','네, 제가 설명한 쪽과 잘 맞습니다.','제가 떠올린 맛과는 다른 것 같습니다. 다시 확인 부탁드립니다.','제가 찾던 맛을 차분히 확인해 주셔서 감사합니다.','기대한 맛과 조금 달라 아쉽습니다.','남은 여행 일정에 어떤 골목을 걸을지 생각하고 있습니다.'),
'cus_china':('오늘 원하는 맛을 재료로 말씀드릴게요.',' 주세요.','对, 제가 말한 방향이에요.','제가 말한 재료와 맛을 다시 확인해 주세요.','원하는 맛을 분명하게 전하고 받을 수 있어서 좋았어요.','재료로 설명한 맛과 달라서 아쉬워요.','마감할 과제와 오늘 장볼 목록을 정리하고 있어요.'),
'cus_child':('오늘은 내가 맛을 골라 볼래요!',' 주세요!','맞아요! 내가 고른 느낌이에요!','내가 고른 맛이랑 달라요. 다시 봐 주세요.','내가 직접 고른 걸 받아서 기뻐요!','내가 생각한 맛은 다른 거였어요.','유치원에서 친구랑 그린 캐릭터를 생각하고 있어요.'),
'cus_student':('오늘 기분에는 이런 맛이 딱일 듯요.',' 부탁해요!','이 느낌 맞아요. 오늘 취향 제대로네요.','제가 말한 느낌이랑 좀 달라요. 한번만 다시 봐주세요.','취향 체크 제대로 돼서 기분 좋아요.','생각한 맛이 아니라 좀 아쉽네요.','시험 끝나고 들을 플레이리스트를 고르고 있어요.'),
'cus_pangyo':('지금 제 입맛 니즈부터 간단히 말씀드릴게요.',' 부탁드려요.','이 정도면 제 취향이랑 싱크 맞네요.','요청한 맛과 결과 사이에 갭이 있어요. 확인 부탁드려요.','입맛 니즈가 잘 반영돼서 다음 일정으로 넘어갈 수 있겠어요.','요청한 맛과 얼라인이 안 돼서 아쉽네요.','팀 일정표에서 다음 회의 시간을 확인하고 있어요.'),
'cus_barista':('오늘은 맛과 추출 느낌을 비교해 보고 싶어요.',' 부탁드립니다.','말씀드린 맛의 균형과 잘 맞네요.','설명드린 바디감과 맛의 방향을 다시 확인해 주시겠어요?','기대한 맛을 직접 비교해 볼 수 있어서 좋았습니다.','설명한 맛의 기준과는 차이가 있어 아쉽습니다.','다음 실습에서 비교할 향과 바디감 메모를 정리하고 있어요.'),
'cus_trainer':('오늘은 제 컨디션에 맞춰 성분부터 고를게요.',' 주세요!','좋아요. 제가 정한 맛과 성분 방향이에요.','제가 말씀드린 성분과 맛을 다시 봐 주실래요?','제 선택대로 챙겨 받아서 다음 일정도 힘내겠어요.','고른 맛과 성분 방향이 달라서 아쉬워요.','오늘 운동 기록과 쉬는 시간을 정리하고 있어요.'),
'cus_blind':('어떤 맛인지 설명을 듣고 제 취향으로 고르고 싶어요.',' 부탁드립니다.','네, 설명한 맛과 제가 고른 방향이 맞네요.','제가 말씀드린 취향 조건을 다시 확인해 주시겠어요?','설명을 듣고 제 선택대로 받을 수 있어서 좋았어요.','말씀드린 취향과 달라서 다시 확인하고 싶네요.','산책하며 들었던 음악의 멜로디를 떠올리고 있어요.')}
items=[];chatter=[]
people=json.loads((res.parent/'Data/personas.json').read_text(encoding='utf-8'))['items']
people = [p for p in people if not p.get('parentPersonaId')]
assert {p['id'] for p in people}==set(styles)
for p in people:
    a=styles[p['id']]
    items.append(dict(id=p['id'],orderOpen=[a[0]],orderClose=[a[1]],matched=[a[2]],correction=[a[3]],ratingGood=[a[4]],ratingBad=[a[5]]))
    # Time thresholds and phase-specific questions are separate retrieved records.
    late={
    'cus_elder':['차례를 꽤 기다렸구먼. 언제 고를 수 있겠나?','기다리는 새 옛이야기가 길어졌구먼. 내 잔은 얼마나 남았나?'],
    'cus_gyeongsang':['장바구니 들고 좀 기다렸네예. 내 차례 됐는교?','내 음료는 아직인교? 기다린 시간이 쪼매 기네예.'],
    'cus_jeolla':['거시기, 기다린 시간이 꽤 됐는디 접수 언제 할까잉?','아까 주문한 잔은 언제 나올까잉? 모임 얘기도 한바탕 했네잉.'],
    'cus_chungcheong':['아직 기다려도 되긴 하는데유, 순서는 알고 싶어유.','괜찮긴 한데유, 주문한 지는 꽤 됐슈. 얼마나 남았어유?'],
    'cus_gangwon':['꽤 기다렸드래요. 이제 주문할 차례인가요?','제 잔은 아직인가요? 산 얘기를 한참 할 만큼 기다렸드래요.'],
    'cus_jeju':['제 차례는 언제쯤이우꽈? 기다림이 길어졌수다.','아까 고른 음료는 언제 나오나요? 기다림이 꽤 길어졌수다.'],
    'cus_sea':['가족 이야기 떠올리다 보니 시간이 꽤 갔네요. 제 순서가 궁금해요.','고향 이야기 한참 할 만큼 기다렸네요. 제 잔은 얼마나 남았나요?'],
    'cus_west':['Excuse me, 제 주문 순서가 언제쯤일까요?','Still waiting, 제 음료가 곧 나올까요? 시간이 꽤 지났어요.'],
    'cus_japan':['오래 기다린 것 같아서요. 접수 순서를 확인 부탁드립니다.','아까 부탁한 잔은 얼마나 남았을까요? 여행 일정도 확인해야 해서요.'],
    'cus_china':['기다린 시간이 꽤 길어요. 제 접수 순서를 알려 주세요.','주문은 했는데 제 잔이 아직이에요. 얼마나 남았나요?'],
    'cus_child':['아직 주문 못 해요? 그림 그릴 만큼 기다렸어요.','내가 고른 음료는 언제 나와요? 꽤 오래 기다렸어요.'],
    'cus_student':['대기 시간이 꽤 긴 듯요. 제 순서도 확인 가능할까요?','시간이 좀 많이 갔는데요. 제 음료 언제쯤 나와요?'],
    'cus_pangyo':['대기 일정이 길어졌네요. 접수 순서 공유 부탁드려요.','주문 이후 딜레이가 길어졌는데요. 준비 일정 확인 부탁드려요.'],
    'cus_barista':['대기가 길어져서요. 접수 가능한 순서를 확인하고 싶습니다.','맛을 비교할 준비는 됐는데 제 잔이 아직이군요. 언제 받을 수 있을까요?'],
    'cus_trainer':['쉬는 시간이 꽤 지났네요! 제 주문 순서는 언제일까요?','다음 일정도 있어서요! 주문한 잔은 얼마나 남았나요?'],
    'cus_blind':['기다린 시간이 길어진 것 같네요. 접수 순서를 알려 주시겠어요?','아까 주문한 음료가 얼마나 남았는지 설명해 주시겠어요?']}
    before,after=late[p['id']]
    chatter.append([ [a[6],before,before+' 순서를 다시 확인하고 싶어요.'],
                     [a[6],after,after+' 기다린 시간도 생각해 주시면 좋겠어요.'] ])
(res/'CafeVocabulary.json').write_text(json.dumps(dict(version=2,items=items),ensure_ascii=False,indent=2),encoding='utf-8')
(res.parent/'Data/ChatterLexicon.json').write_text(json.dumps(dict(items=[dict(personaId=p['id'],inactive=c[0],active=c[1]) for p,c in zip(people,chatter)]),ensure_ascii=False,indent=2),encoding='utf-8')

# Reapply independent branches after rebuilding the original source tables.
import runpy
runpy.run_path(str(Path(__file__).with_name('apply-cafe-persona-branches.py')), run_name='__main__')
